private CommandResult LaunchWithCurrentValues()
{
    var target = BuildEvaluatedBookmark();
    var classification = _resolver.ClassifyOrUnknown(target);
    var success = CommandLauncher.Launch(classification);
    if (!success)
    {
        return CommandResult.KeepOpen();
    }

    foreach (var run in _placeholderRuns.Values)
    {
        run.ClearValue();
    }

    return CommandResult.Dismiss();
}

private readonly Func<Classification, bool> _launch;

// Production construction binds _launch = CommandLauncher.Launch.
// The friend-test construction path supplies _launch = _ => true or _ => false.

var success = _launch(classification);
